// BST above: 8, left 3 (right child 6), right 10
Node cur = root;
int steps = 0;
while (cur != null && cur.val != 6) {
    cur = (6 < cur.val) ? cur.left : cur.right;
    steps++;
}
System.out.println(steps);

// BST above: 5 (left 3, right 8) — inserting 7
Node cur = root;
while (true) {
    Node nxt = (7 < cur.val) ? cur.left : cur.right;
    if (nxt == null) {
        if (7 < cur.val) cur.left = new Node(7); else cur.right = new Node(7);
        break;
    }
    cur = nxt;
}
System.out.println("value " + root.right.left.val);

